import{_ as r,c as p,o as e,a5 as o}from"./chunks/framework.DorIfSpC.js";const c=JSON.parse('{"title":"我把上一篇刪掉的那一步，加了回來","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/storyboard-before-render"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/storyboard-before-render"}],["meta",{"property":"og:title","content":"我把上一篇刪掉的那一步，加了回來 | 星智未來"}],["meta",{"name":"twitter:title","content":"我把上一篇刪掉的那一步，加了回來 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"我把上一篇刪掉的那一步，加了回來\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/storyboard-before-render\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/storyboard-before-render\\"}}"]]},"headers":[],"relativePath":"project/storyboard-before-render.md","filePath":"project/storyboard-before-render.md","lastUpdated":1787544889000}'),a={name:"project/storyboard-before-render.md"};function n(s,t,l,d,i,h){return e(),p("div",null,[...t[0]||(t[0]=[o('<h1 id="我把上一篇刪掉的那一步-加了回來" tabindex="-1">我把上一篇刪掉的那一步，加了回來 <a class="header-anchor" href="#我把上一篇刪掉的那一步-加了回來" aria-label="Permalink to &quot;我把上一篇刪掉的那一步，加了回來&quot;">​</a></h1><blockquote><p>一張空桌子、九個不一樣的房間，和一個 20 秒就能抓到的錯</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 8 月 20 日</p><hr><p>上一篇我寫的是怎麼刪掉關鍵幀——43 張圖、18 次重做、4 到 5 個小時，那一段不是變快了，是不存在了。</p><p>這一篇我要說：<strong>我把一個東西加了回來。</strong></p><p>不是關鍵幀。是別的。而且我花了兩天才看懂它們的差別。</p><hr><h2 id="先看那張空桌子" tabindex="-1">先看那張空桌子 <a class="header-anchor" href="#先看那張空桌子" aria-label="Permalink to &quot;先看那張空桌子&quot;">​</a></h2><p>我要做的是主題曲 MV 的一段，35 秒，三顆鏡頭。</p><p>我寫了三份 prompt，跑出來，看起來都對——角色沒崩、手沒有六根指頭、切鏡準時。技術上沒有任何問題。</p><p>然後我把它拿給人看，得到四個字：</p><p><strong>「太乾了。」</strong></p><p>三顆鏡頭全在同一張桌子前。同一個早上、同一個角度、只有一個女生和一隻貓。35 秒沒有任何變化。</p><p>我回去翻自己寫的 prompt，找到這句：</p><blockquote><p>The desk is otherwise bare. 桌上除此之外是空的。</p></blockquote><p><strong>那不是模型生成的。那是我打的字。</strong></p><hr><h2 id="我在解錯的問題" tabindex="-1">我在解錯的問題 <a class="header-anchor" href="#我在解錯的問題" aria-label="Permalink to &quot;我在解錯的問題&quot;">​</a></h2><p>我為什麼會寫「桌上是空的」？</p><p>因為我腦子裡跑的是這種清單：</p><ul><li>一支 clip 只給一個運鏡，多了會糊</li><li>切點不要超過一個，多了身份會漂</li><li>場景固定，減少變因</li><li>畫面裡東西越少，越不容易生出怪東西</li></ul><p>每一條單獨看都對。它們都來自實測，都有道理。</p><p><strong>但它們是「怎麼讓生成不出錯」的規則，不是「怎麼讓畫面好看」的規則。</strong></p><p>我把分鏡當成一個工程問題在解。而工程問題的最佳解，是把所有會出錯的東西都拿掉——最後剩下一張空桌子和兩個角色。</p><p>穩定，而且沒有人想看。</p><hr><h2 id="兩種圖-長得一樣" tabindex="-1">兩種圖，長得一樣 <a class="header-anchor" href="#兩種圖-長得一樣" aria-label="Permalink to &quot;兩種圖，長得一樣&quot;">​</a></h2><p>重寫分鏡的時候我想通一件事。</p><p>上一篇刪掉的關鍵幀，和我現在要加回來的東西，<strong>產出物長得一模一樣：都是一張圖</strong>。</p><p>但它們在流程裡的位置完全不同。</p><p><strong>關鍵幀是餵給模型的。</strong> 它是 I2VA 的第一格，模型從那一格往下演。沒有它，模型不知道畫面該長什麼樣。Ref2VA 讓這件事變得不必要——你給角色照片就好，構圖交給文字。</p><p><strong>分鏡草圖是餵給你自己的眼睛的。</strong> 它不進模型，它進你的判斷。它回答的是「我寫的這段文字，變成畫面之後長什麼樣」。</p><p>我刪掉關鍵幀的時候，<strong>沒注意到自己順手也刪掉了第二種</strong>。</p><p>因為它們長一樣，我以為刪掉一個就是刪掉一個。</p><hr><h2 id="_20-秒-vs-8-分鐘" tabindex="-1">20 秒 vs 8 分鐘 <a class="header-anchor" href="#_20-秒-vs-8-分鐘" aria-label="Permalink to &quot;20 秒 vs 8 分鐘&quot;">​</a></h2><p>加回來的方法很土：寫完 prompt，先用圖像模型生一張靜態的，看過再送去算影片。</p><p>九張草圖，一張約 20 秒。</p><p><strong>跑完抓到三個錯。</strong></p><p><strong>第一個：公仔變成落地燈。</strong></p><p>那是個桌上型的裝置，實體大約 16 公分。但在全景鏡頭裡，模型沒有尺度參照，就把它畫成地板上一顆 60 公分的發光物體。</p><p>我原本的 prompt 只寫 <code>small ornament</code>。<strong>模型對「small」沒有共識。</strong></p><p>修法要三招疊：跟已知物體比（大約她的手掌長）、給絕對尺寸（16 公分）、明確排除（不是落地燈）。</p><p><strong>第二個：夜景把貓的顏色洗掉了。</strong></p><p>我在分鏡裡寫「房間唯一的光源是貓肚子的暖光」。聽起來很美。</p><p>結果整隻貓被自己的光染成橘色——奶油白的身體、左橘右灰的耳朵、眼睛的金環，全部消失，變成一團橘色。</p><p>沒有補光就沒有對照，物體只會呈現光源的顏色。這是攝影的基本常識，我卻在分鏡裡把它寫成規則。</p><p>加一道冷色月光就好了。但關鍵是<strong>那句話要寫成「因為有月光，所以貓的顏色讀得出來」</strong>——只寫「有月光」，模型會把它當背景，不會拿它來照東西。</p><p><strong>第三個：兩張床。</strong></p><p>一張圖裡出現了兩張床。她靠著一張，旁邊還有一張。</p><p>這個錯最有意思，因為它指向一個更深的問題。</p><hr><h2 id="場景也是資產" tabindex="-1">場景也是資產 <a class="header-anchor" href="#場景也是資產" aria-label="Permalink to &quot;場景也是資產&quot;">​</a></h2><p>九張草圖，我是一張一張生的。</p><p>角色我有參考圖——女主角的照片、公仔的算圖，每張都餵進去。所以九張圖裡的人和貓都長一樣。</p><p><strong>房間我沒有參考圖。</strong></p><p>所以模型每一張都在重新編一個房間。九張圖，九個不一樣的房間。其中一張湊出了兩張床。</p><p>角色有資產，場景沒有。這個不對稱是根因，而我一直沒看見——因為我從來沒把「房間」當成一個需要被定義的東西。</p><p>補法很直接：生一張房間的定裝照。台灣的租屋處，單人床靠左、書桌在右邊窗下、木地板、窗外對面樓的電線和一塊「五金行」的招牌。乾淨的白天光線，看得清楚格局。</p><p>然後把它當第三個角色餵進每一支 clip。</p><p><strong>接下來的事情有點神奇。</strong> 那張參考圖是白天拍的，但我要的是夜戲——她坐在地板上，房間只有一盞暖光。</p><p>文字寫夜，圖給白天。</p><p>跑出來是同一個房間的夜晚。床在左、桌在右、椅背同一件外套、地上同一本翻開的書、床邊同一個帆布袋，窗外連那塊「五金行」都在。只是天黑了。</p><p><strong>參考圖鎖住幾何，文字控制光線。</strong> 一張日景撐起了整段的四個場景。</p><hr><h2 id="我在同一個坑裡跌了四次" tabindex="-1">我在同一個坑裡跌了四次 <a class="header-anchor" href="#我在同一個坑裡跌了四次" aria-label="Permalink to &quot;我在同一個坑裡跌了四次&quot;">​</a></h2><p>回頭看兩天的紀錄，有一類錯我犯了四次：</p><table tabindex="0"><thead><tr><th>我寫的</th><th>參考圖裡實際上</th><th>結果</th></tr></thead><tbody><tr><td>眼睛是暗的、關著的</td><td>黑底 ＋ 金環 ＋ 高光</td><td>金環一起被抹黑，變成空眼窩</td></tr><tr><td>眼睛是亮的、淡的</td><td>黑底 ＋ 金環 ＋ 高光</td><td>方向相反的同一個錯</td></tr><tr><td>肚子沒有亮</td><td>肚子在發光</td><td>兩邊打架</td></tr><tr><td>沒有關節、不會動</td><td>一隻舉起的手</td><td>手照樣揮，而且畫面整體變差</td></tr></tbody></table><p><strong>共同點：我用形容詞去描述一個參考圖裡不存在的狀態。</strong></p><p>文字在跟圖片搶，而圖片通常會贏。</p><p>最後一列還多犯一個錯——「沒有會動的部件」這句話裡有「會動」。模型沒有負向通道可以扣掉它，讀到的只有「moving parts」。</p><p>正解只有兩條：<strong>指向參考圖</strong>（as in Picture 1），或者<strong>去生一張那個狀態的圖</strong>。</p><p>後者是這個專案的合作者提的。她說：那就多做一張睡眼的參考圖吧。</p><p>一張圖解決了我三次改文字沒解決的事。</p><hr><h2 id="同一句話-兩個工具-相反的效果" tabindex="-1">同一句話，兩個工具，相反的效果 <a class="header-anchor" href="#同一句話-兩個工具-相反的效果" aria-label="Permalink to &quot;同一句話，兩個工具，相反的效果&quot;">​</a></h2><p>還有一個發現值得單獨記。</p><p>修公仔尺寸的時候，我在圖像模型的 prompt 裡加了一句：</p><blockquote><p>It must never look like a floor lamp.</p></blockquote><p><strong>有效。</strong> 尺寸立刻對了。</p><p>但這句話我<strong>不能</strong>搬到影片模型上。H3 在 ComfyUI 裡跑的是單一條件通道，沒有負向輸入。寫「不要像落地燈」等於把「落地燈」塞進條件裡。</p><p>同一句話，在生圖工具有效，在生影片工具會反效果。</p><p><strong>工具的規則不能互相搬。</strong> 這聽起來很基本，但我在三個地方犯過——尺度錨點、冷色補光、場景參考，每一次都是在圖像那邊修好了，忘記同步到影片那邊。</p><hr><h2 id="帳單" tabindex="-1">帳單 <a class="header-anchor" href="#帳單" aria-label="Permalink to &quot;帳單&quot;">​</a></h2><p>六支 clip，主機開了 40 分鐘。</p><p>$2.09 一小時，<strong>總共 NT$45</strong>。成品 35.458 秒，每秒約 1.3 塊。</p><p>九張草圖的成本是幾角美金，時間三分鐘。</p><p><strong>那三分鐘抓到的三個錯，每一個在影片階段都要 8 分鐘才會浮出來</strong>，而且抓到之後還要再花 8 分鐘重跑。</p><hr><h2 id="所以我到底加回了什麼" tabindex="-1">所以我到底加回了什麼 <a class="header-anchor" href="#所以我到底加回了什麼" aria-label="Permalink to &quot;所以我到底加回了什麼&quot;">​</a></h2><p>不是關鍵幀。關鍵幀還是不用畫——Ref2VA 那條路是通的，上一篇沒有寫錯。</p><p>我加回來的是**「先看一眼」**。</p><p>它剛好也是一張圖，所以我把它跟關鍵幀當成同一件事，一起刪掉了。</p><p>但關鍵幀是模型的輸入，草圖是你的輸入。刪掉前者省下四五個小時；刪掉後者，你會在八分鐘之後才發現桌上什麼都沒有。</p><p>上一篇的結論我到現在還同意：真正貴的從來不是 GPU。</p><p><strong>只是這次貴的不是那四五個小時，是我對著一支跑好的片子才發現方向錯了。</strong></p><p>想自己試一個下午：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a>。</p><hr><p><em>本文的實測環境為 RunPod 租用之 RTX PRO 6000 Blackwell（$2.09/hr），影片模型為 MiniMax H3 開源權重於 ComfyUI 本地部署，分鏡草圖使用 Gemini 圖像模型。</em></p><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>',103)])])}const m=r(a,[["render",n]]);export{c as __pageData,m as default};
